@@ -1,6 +1,7 @@
 use crate::io::util::write_all_buf::WriteAllBufState;
 use crate::io::{AsyncWrite, AsyncWriteExt, ReadBuf};
 use crate::util::poll::poll_never;
+use std::io::IoSlice;
 use std::pin::Pin;
 use std::task::{Context, Poll};

@@ -44,10 +45,14 @@ where
     {
         let mut me = self.as_mut().project();

-        let mut buf = me.buf.take().unwrap();
-        let chunk = buf.chunk();
-        let n = ready!(me.w.as_mut().poll_write(cx, chunk))?;
-        buf.advance(n);
+        let mut buf = me.buf.take().unwrap();
+
+        if me.w.is_write_vectored() {
+            let mut slices = [IoSlice::new(&[]); 8];
+            let n = ready!(me.w.as_mut().poll_write_vectored(cx, &mut slices))?;
+            buf.advance(n);
+        } else {
+            let chunk = buf.chunk();
+            let n = ready!(me.w.as_mut().poll_write(cx, chunk))?;
+            buf.advance(n);
+        }
+
         me.buf.set(Some(buf));
